-- Example 3NF Table Decomposition
-- Bad (Transitive Dependency: StudentID -> DeptID -> DeptName):
CREATE TABLE Student_Bad (StudentID INT, StudentName VARCHAR(50), DeptID INT, DeptName VARCHAR(50));

-- Good (Normalized to 3NF):
CREATE TABLE Department (DeptID INT PRIMARY KEY, DeptName VARCHAR(50));
CREATE TABLE Student (StudentID INT PRIMARY KEY, StudentName VARCHAR(50), DeptID INT REFERENCES Department(DeptID));

